import 'package:flutter/material.dart';
import 'package:lazerus_core/lazerus_core.dart';

import '../../../../../core/macros/triggers/multiband_eq/multiband_eq_trigger.dart';
import '../../multiband_eq_editor.dart';
import '../macro_editor_node_module.dart';

final class MultibandEqMacroEditorNodeModule extends MacroEditorNodeModule
    implements MacroEditorStarterNodeModule {
  MultibandEqMacroEditorNodeModule() : _factory = MultibandEqTriggerFactory();

  final MultibandEqTriggerFactory _factory;

  @override
  String get kind => multibandEqTriggerKind;

  @override
  MacroEditorStarterRole get starterRole => MacroEditorStarterRole.processor;

  @override
  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) => <MacroEditorPaletteEntry>[
    const MacroEditorPaletteEntry(
      id: 'palette.multiband-eq',
      moduleKind: multibandEqTriggerKind,
      section: MacroEditorPaletteSection.modules,
      icon: Icons.graphic_eq,
      title: 'Multiband EQ',
      subtitle: 'Audio analysis trigger',
    ),
  ];

  @override
  MacroNode createStarterNode({required MacroEditorNewId newId}) =>
      _createNode(newId());

  @override
  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) => _createNode(newId());

  @override
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) {
    try {
      final configuration = MultibandEqTriggerConfiguration.fromNodeParameters(
        nodeContext.node.parameters,
      );
      final telemetry = nodeContext.state.runtime?.lastTelemetry;
      return MacroEditorNodeInspectorCard(
        title: titleFor(nodeContext.node),
        enabled: nodeContext.state.enabled,
        onRemove: nodeContext.removeNode,
        child: MultibandEqEditor(
          configuration: configuration,
          spectrumValues: telemetry?.spectrum?.levels ?? const <double>[],
          spectrumFrequenciesHz:
              telemetry?.spectrum?.frequenciesHz ?? const <double>[],
          enabled: nodeContext.state.enabled,
          onChanged: (updated) => nodeContext.replaceNode(
            _nodeWithConfiguration(nodeContext.node, updated),
          ),
        ),
      );
    } on FormatException catch (error) {
      return MacroEditorNodeErrorCard(
        message: 'EQ configuration needs repair: $error',
      );
    }
  }

  MacroNode _createNode(String id) => _nodeWithConfiguration(
    MacroNode(
      id: id,
      kind: kind,
      displayName: 'Multiband EQ',
      ports: const <MacroPortDeclaration>[],
    ),
    MultibandEqTriggerConfiguration(
      bands: <MultibandEqBandDefinition>[
        _defaultLevelBand('low', 20, 250),
        _defaultLevelBand('mid', 250, 2000),
        _defaultLevelBand('high', 2000, 8000),
      ],
    ),
  );

  MacroNode _nodeWithConfiguration(
    MacroNode node,
    MultibandEqTriggerConfiguration configuration,
  ) {
    final configured = node.copyWith(
      parameters: configuration.toNodeParameters(),
    );
    return configured.copyWith(ports: _factory.portsFor(configured));
  }

  MultibandEqBandDefinition _defaultLevelBand(
    String id,
    double lowerFrequencyHz,
    double upperFrequencyHz,
  ) => MultibandEqBandDefinition(
    id: id,
    lowerFrequencyHz: lowerFrequencyHz,
    upperFrequencyHz: upperFrequencyHz,
    mode: MultibandEqBandMode.level,
    normalizationMinimum: multibandEqMinimumDbfs,
    normalizationMaximum: multibandEqMaximumDbfs,
    outputBuffer: const Duration(milliseconds: 50),
  );
}
